@pytest.mark.parametrize(
    "kind",
    [
        pytest.param(hookimpl(wrapper=True), id="wrapper"),
        pytest.param(hookimpl(hookwrapper=True), id="legacy-wrapper"),
    ],
)
def test_wrappers_yield_never_fails(pm: PluginManager, kind: Any) -> None:
    class Plugin:
        @kind
        def wrap(self):
            if False:
                yield  # type: ignore[unreachable]

    pm.register(Plugin())
    with pytest.raises(RuntimeError, match="wrap_controller at 'wrap'.* did not yield"):
        pm.hook.wrap()

def test_warn_when_deprecated_args_specified(recwarn) -> None:
    warning1 = DeprecationWarning("old1 is deprecated")
    warning2 = DeprecationWarning("old2 is deprecated")

    class Spec:
        @hookspec(
            warn_on_impl_args={
                "old1": warning1,
                "old2": warning2,
            },
        )
        def foo(self, old1, new, old2):
            raise NotImplementedError()

    class Plugin:
        @hookimpl
        def foo(self, old2, old1, new):
            raise NotImplementedError()

    pm = PluginManager(hookspec.project_name)
    pm.add_hookspecs(Spec)

    with pytest.warns(DeprecationWarning) as records:
        pm.register(Plugin())
    (record1, record2) = records
    assert record1.message is warning2
    assert record1.filename == Plugin.foo.__code__.co_filename
    assert record1.lineno == Plugin.foo.__code__.co_firstlineno
    assert record2.message is warning1
    assert record2.filename == Plugin.foo.__code__.co_filename
    assert record2.lineno == Plugin.foo.__code__.co_firstlineno

def test_register_instance_attribute_bound_method(he_pm: PluginManager) -> None:
    """A bound method stored on the instance stays bound to its own object."""

    class Impl:
        @hookimpl
        def he_method1(self, arg: object) -> list[object]:
            return [self, arg]

    impl = Impl()

    class Plugin:
        pass

    plugin = Plugin()
    plugin.he_method1 = impl.he_method1  # type: ignore[attr-defined]

    he_pm.register(plugin)
    assert he_pm.hook.he_method1(arg=1) == [[impl, 1]]
